    /*
     * Add to the Manufacturers
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Supplier
     */
    public Supplier addToManufacturers( UUID parentId, AerospaceManufacturer addTo ) {
	    LOGGER.info("handling AssignManufacturersToSupplierEvent - " );
	    
	    Supplier parentEntity = repository.findById(parentId).get();
	    AerospaceManufacturer child = registry.project( AerospaceManufacturer.class, addTo.getAerospaceManufacturerId());
	    
	    parentEntity.getManufacturers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

